let state;try{state=JSON.parse(localStorage.getItem('discrete-v1'))||{done:[],answers:{}}}catch{state={done:[],answers:{}}}const app=document.querySelector('#app');const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function save(){try{localStorage.setItem('discrete-v1',JSON.stringify(state))}catch{}document.querySelector('#wc').textContent=Object.values(state.answers).filter(x=>!x.correct).length}function nav(){let s=document.querySelector('#search').value.toLowerCase(),g='';document.querySelector('#nav').innerHTML='<a href="#home">⌂ 学习概览</a>'+lessons.filter(l=>(l.title+l.body).toLowerCase().includes(s)).map(l=>{let h=l.group!==g?`<h4>${g=l.group}</h4>`:'';return h+`<a class="${location.hash==='#lesson-'+l.id?'active':''}" href="#lesson-${l.id}">${String(l.id+1).padStart(2,'0')}　${l.title}${state.done.includes(l.id)?' ✓':''}</a>`}).join('')}function home(){document.querySelector('#crumb').textContent='学习概览';let next=lessons.find(l=>!state.done.includes(l.id))||lessons[0];app.innerHTML=`<section class="hero"><div><span class="eyebrow">A LITTLE LOGIC, EVERY DAY</span><h1>把离散的知识，<br>连成清晰的思路。</h1><p>从一个命题，到一张图，再到抽象的代数结构。沿着你的笔记循序渐进，在每一次练习中理解数学的语言。</p><div class="actions"><a class="button primary" href="#lesson-${next.id}">继续学习 · ${next.title} →</a><a class="button" href="#catalog">浏览课程目录</a></div></div><div class="art">∀ → ∞</div></section><div class="stats"><div><strong>17</strong><span>笔记章节</span></div><div><strong>73</strong><span>完整笔记小节</span></div><div><strong>272</strong><span>原页完整收录</span></div><div><strong>${state.done.length}/17</strong><span>已学章节</span></div></div><section><span class="eyebrow">YOUR LEARNING PATH</span><h2>每一章，都走稳四步</h2><p>① 阅读概念与公式　→　② 跟随例题理解　→　③ 独立完成练习　→　④ 对照解析与原笔记</p></section><section id="catalog"><h2>课程目录 <small class="tag">按笔记顺序 · 四个学习模块</small></h2><div class="grid">${lessons.map(l=>`<a class="card" href="#lesson-${l.id}"><span class="num">CHAPTER ${String(l.id+1).padStart(2,'0')}　${state.done.includes(l.id)?'✓ 已学':''}</span><h3>${l.title}</h3><p>${l.intro}</p><span class="tag">${l.group} · ${sections.filter(s=>s.chapter===l.id).length} 小节 · ${l.start}–${l.end} 页　↗</span></a>`).join('')}</div></section><section class="box"><h3>内容说明与学习建议</h3><p>本学习站按17章、73小节收录全部272页笔记。每个小节直接展示完整手写原页，包括公式、推导、证明、图形和批注，可放大阅读。章节导学与练习是补充材料。原页影像完整收录不等于已逐字转写，文字校订尚未完成。</p><p>指定教材：《离散数学》第七版。具体作者、出版社与ISBN待核对；当前章号和小节号严格沿用这份笔记，不将其他版本目录冒充为第七版目录。</p><p class="note">进度与错题仅保存在当前浏览器。建议每次学习1章，先作答，再查看解析。</p></section>`}function question(l,q,i){let key=l.id+'-'+i;return `<div class="box"><span class="tag">${i===0?'单项选择':'填空题'} · ${l.title}</span><h3>${esc(q.q)}</h3><form data-key="${key}">${q.options?q.options.map((o,j)=>`<label class="option"><input type="radio" name="answer" value="${j}" required>${String.fromCharCode(65+j)}. ${esc(o)}</label>`).join(''):'<label>你的答案（填写一个整数） <input name="answer" inputmode="numeric" autocomplete="off" required></label>'}<div class="actions"><button class="primary" type="submit">提交答案</button><button type="button" data-explain="${key}">查看解析</button></div><div class="feedback" aria-live="polite" id="feedback-${key}"></div></form></div>`}function lesson(id){let l=lessons[id];if(!l){location.hash='home';return}document.querySelector('#crumb').textContent=l.title;app.innerHTML=`<article class="lesson"><span class="eyebrow">CHAPTER ${String(id+1).padStart(2,'0')} / ${l.group}</span><h1>${l.title}</h1><p>${l.intro}</p><div class="actions"><a class="button" href="notes/${id+1}.pdf" target="_blank">阅读原笔记 · 第${l.start}–${l.end}页 ↗</a><a class="button" href="#practice">进入练习 ↓</a></div>${sectionCatalog(l)}<details class="box"><summary>补充导学 · 核心概念与例题</summary><section><span class="tag">01 / 理解概念</span><h2>核心知识</h2><p>${l.body}</p><div class="formula">${l.formula}</div></section><section class="box"><span class="tag">02 / 跟随例题</span><h2>把定义用起来</h2><p>${l.example}</p></section><div class="warn"><strong>易错提醒</strong><br>${l.pitfall}</div></details><section id="practice"><span class="tag">03 / 独立练习</span><h2>现在，检验你的理解</h2>${l.questions.map((q,i)=>question(l,q,i)).join('')}</section><div class="actions"><button class="primary" id="done">${state.done.includes(id)?'已标记学完 ✓':'标记本章学完 ✓'}</button>${id<16?`<a class="button" href="#lesson-${id+1}">下一章 →</a>`:'<a class="button" href="#home">返回概览</a>'}</div></article>`;document.querySelector('#done').onclick=()=>{if(!state.done.includes(id))state.done.push(id);save();nav();document.querySelector('#done').textContent='已标记学完 ✓'}}function explain(key,prefix=''){let [id,i]=key.split('-').map(Number),q=lessons[id].questions[i];document.getElementById('feedback-'+key).textContent=prefix+'答案：'+(q.options?String.fromCharCode(65+Number(q.answer))+'. '+q.options[q.answer]:q.answer)+'\n解析：'+q.why}app.addEventListener('submit',e=>{e.preventDefault();let key=e.target.dataset.key,[id,i]=key.split('-').map(Number),value=new FormData(e.target).get('answer').trim().replace(/[０-９]/g,c=>String(c.charCodeAt(0)-65296));let correct=value===lessons[id].questions[i].answer;state.answers[key]={correct,value};save();explain(key,correct?'✓ 回答正确。\n':'再想一想。\n');document.getElementById('feedback-'+key).className='feedback '+(correct?'correct':'incorrect')});app.addEventListener('click',e=>{let b=e.target.closest('[data-explain]');if(b)explain(b.dataset.explain)});document.querySelector('#wrong').onclick=()=>{location.hash='wrong'};document.querySelector('#search').oninput=nav;function route(){if(location.hash==='#practice'||location.hash==='#catalog')return;nav();if(location.hash.startsWith('#section-')){readSection(location.hash.slice(9));return}else if(location.hash.startsWith('#lesson-'))lesson(Number(location.hash.slice(8)));else if(location.hash==='#wrong'){document.querySelector('#crumb').textContent='错题回顾';let keys=Object.keys(state.answers).filter(k=>!state.answers[k].correct);app.innerHTML='<section class="lesson"><h1>把疑惑，变成理解。</h1><p>重新作答正确后，题目会从下次错题回顾中移除。</p>'+ (keys.length?keys.map(k=>{let [id,i]=k.split('-').map(Number);return question(lessons[id],lessons[id].questions[i],i)}).join(''):'<div class="box">目前没有错题。去课程中完成练习吧。</div>')+'</section>'}else home();window.scrollTo(0,0)}window.onhashchange=route;save();route();

function sectionCatalog(l){return `<section class="box"><span class="tag">完整笔记正文 · ${l.end-l.start+1} 页</span><h2>本章小节</h2><p>进入小节即可直接阅读全部原页。原始公式、证明、图表和手写批注均保留。</p><div class="section-list">${sections.filter(s=>s.chapter===l.id).map(s=>`<a href="#section-${s.key}"><b>${s.key}　${s.title}</b><span>第 ${s.start}–${s.end} 页 →</span></a>`).join('')}</div></section>`}
function readSection(key){const s=sections.find(x=>x.key===key);if(!s){location.hash='home';return}const index=sections.indexOf(s);document.querySelector('#crumb').textContent=lessons[s.chapter].title+' / '+s.key;app.innerHTML=`<article class="fullnotes"><a href="#lesson-${s.chapter}">← ${lessons[s.chapter].title} · 本章目录</a><h1>${s.key} ${s.title}</h1><p>原笔记第 ${s.start}–${s.end} 页 · 共 ${s.end-s.start+1} 页 · 完整原页影像</p>${transcripts[s.key]?`<section class="box transcript">${transcripts[s.key]}</section>`:""}<div class="reader-controls"><label>跳转到本节页码 <select id="page-select">${Array.from({length:s.end-s.start+1},(_,i)=>`<option value="${s.start+i}">${s.start+i}</option>`).join('')}</select></label><button id="zoom-pages">放大阅读</button><button id="read-done">标记本节已读</button></div><p class="note">下方为笔记正文，完整保留推导、例题、图形与边注。点击页图可独立打开高清图。手写内容尚未全部转成可搜索文字。</p>${Array.from({length:s.end-s.start+1},(_,i)=>{const n=s.start+i;const src='pages/'+String(n).padStart(3,'0')+'.jpg';return `<figure class="note-page" id="note-page-${n}"><figcaption>${s.key} ${s.title} · 原笔记第 ${n} 页</figcaption><a href="${src}" target="_blank" rel="noopener" aria-label="打开第${n}页高清图"><img src="${src}" loading="${i?'lazy':'eager'}" alt="${s.title}，原笔记第${n}页：完整手写内容，含公式、推导和批注"></a></figure>`}).join('')}<div class="actions">${index?`<a class="button" href="#section-${sections[index-1].key}">← 上一节</a>`:''}${index<sections.length-1?`<a class="button primary" href="#section-${sections[index+1].key}">下一节 →</a>`:''}<a class="button" href="#lesson-${s.chapter}">本章练习</a></div></article>`;document.querySelector('#page-select').onchange=e=>document.getElementById('note-page-'+e.target.value).scrollIntoView({behavior:'smooth'});document.querySelector('#zoom-pages').onclick=e=>{const big=document.querySelector('.fullnotes').classList.toggle('zoomed');e.target.textContent=big?'适应宽度':'放大阅读'};let read;try{read=JSON.parse(localStorage.getItem('discrete-read-sections'))||[]}catch{read=[]}const done=document.querySelector('#read-done');if(read.includes(key))done.textContent='本节已读 ✓';done.onclick=()=>{if(!read.includes(key))read.push(key);try{localStorage.setItem('discrete-read-sections',JSON.stringify(read))}catch{}done.textContent='本节已读 ✓'};window.scrollTo(0,0)}
const oldNav=nav;nav=function(){oldNav();const term=document.querySelector('#search').value.trim();if(term){const matches=sections.filter(s=>(s.key+' '+s.title).toLowerCase().includes(term.toLowerCase()));document.querySelector('#nav').insertAdjacentHTML('beforeend','<h4>笔记小节</h4>'+matches.map(s=>`<a href="#section-${s.key}">${s.key} ${s.title}</a>`).join(''))}};route();
